    const { smtp, username, password } = this.settings;
    const transport = nodemailer_default.createTransport({
      host: smtp.host,
      port: smtp.port,
      secure: smtp.secure,
      requireTLS: smtp.starttls,
      auth: { user: username, pass: password },
      connectionTimeout: 20000
    });
    const recipients = [...to, ...input.cc ?? []];
    let info;
    try {
      info = await transport.sendMail({
        envelope: { from: this.settings.address, to: recipients },
        raw
      });
    } catch (error) {
      throw new Error(`${this.settings.smtp.host} did not accept the message: ${error instanceof Error ? error.message : String(error)}`);
    } finally {
      transport.close();
    }
    let savedToSent = null;
    if (!/(^|\.)gmail\.com$/i.test(smtp.host)) {
      savedToSent = await this.session(async (client) => {
        const sent = (await this.folders(client)).SENT;
        if (!sent)
          return null;
        await client.append(sent, raw, ["\\Seen"]);
        return sent;
      }).catch(() => null);
    }
    return {
      messageId,
      accepted: info.accepted.map(String),
      rejected: info.rejected.map(String),
      savedToSent
    };
  }
}

