    host: /<hostname>([^<]+)<\/hostname>/.exec(match[1])?.[1]?.trim(),
    port: /<port>(\d+)<\/port>/.exec(match[1])?.[1],
    socket: /<socketType>([^<]+)<\/socketType>/.exec(match[1])?.[1]?.trim()
