        id = created.replies?.[0]?.[`create${K}`]?.[`${kind}Id`];
        if (!id)
          throw new Error(`Google did not return the new ${kind} id`);
        revision = created.writeControl?.requiredRevisionId;
        content = [];
      }
      const first = content[0]?.startIndex ?? 0, end = content.at(-1)?.endIndex ?? first + 1, requests = [];
      if (end - 1 > first)
        requests.push({ deleteContentRange: { range: { segmentId: id, startIndex: first, endIndex: end - 1 } } });
      if (text)
        requests.push({ insertText: { location: { segmentId: id, index: first }, text } });
      if (!requests.length)
        return { segmentId: id, revisionId: doc.revisionId };
      const result = await batch(a.documentId, requests, revision);
      return { segmentId: id, revisionId: result.writeControl?.requiredRevisionId ?? null };
    })
  ];
}
