      const rels = relationships('ppt/presentation.xml');
      const ordered = [...strFromU8(zip['ppt/presentation.xml']).matchAll(/<p:sldId\b[^>]*\br:id=["']([^"']+)["']/g)].map(m => rels.get(m[1]!)?.target);
