         {"query": {"type": "string", "minLength": 1, "maxLength": 256, "description": "Text to find inside messages."},
          "chatGuid": CHAT_GUID,
          "since": {"type": "string", "minLength": 1, "description": "Only messages at or after this time: " + TIME + "."},
